<script setup lang="ts">import {computed,ref} from 'vue';import {useQuery} from '@tanstack/vue-query';import {crmRepository} from '../../services/crmRepository';import EntityDetailPanel from '../../components/common/EntityDetailPanel.vue';import CrmEntityForm from '../../components/crm/CrmEntityForm.vue';import ProjectProgressPanel from '../../components/project/ProjectProgressPanel.vue';import EntityTable from '../../components/common/EntityTable.vue';const keyword=ref('');const selected=ref<Record<string,unknown>|null>(null);const editorOpen=ref(false);const saving=ref(false);const saveError=ref('');const detail=ref<Record<string,unknown>|null>(null);const detailLoading=ref(false);const detailError=ref('');const query=useQuery({queryKey:['projects'],queryFn:()=>crmRepository.projects({page:1,pageSize:100})});const edit=()=>{editorOpen.value=true;saveError.value=''}; const save=async(value:Record<string,unknown>)=>{saving.value=true;try{await crmRepository.updateProject(String(selected.value?.id),value);detail.value=await crmRepository.project(String(selected.value?.id));editorOpen.value=false;await query.refetch()}catch(e){saveError.value=e instanceof Error?e.message:'保存失败'}finally{saving.value=false}};const openDetail=async(item:Record<string,unknown>)=>{selected.value=item;detail.value=null;detailLoading.value=true;detailError.value='';try{detail.value=await crmRepository.project(String(item.id))}catch(e){detailError.value=e instanceof Error?e.message:'项目详情加载失败'}finally{detailLoading.value=false}};const rows=computed(()=>{const items=query.data.value?.items||[];const key=keyword.value.trim().toLowerCase();return key?items.filter(item=>Object.values(item).some(v=>String(v??'').toLowerCase().includes(key))):items});</script>
<template><section class="crm-view"><div class="section-heading"><div><span class="eyebrow">PROJECTS</span><h2>项目列表</h2></div><button class="secondary" @click="query.refetch()">刷新</button></div><div class="toolbar"><input v-model="keyword" placeholder="搜索项目"/><span>{{rows.length}} 条记录</span></div><div v-if="query.isPending" class="state">正在加载项目…</div><div v-else-if="query.isError" class="state error">项目加载失败。</div><div v-else-if="!rows.length" class="state">暂无项目。</div><EntityTable v-else :columns="['项目名称','客户','状态','负责人','创建时间']" :rows="rows" :cell="(item,index)=>[item.name,item.customerName,item.status,item.ownerName,item.createdAt][index]||'—'" @select="openDetail($event)"/><EntityDetailPanel :open="Boolean(selected)" title="项目详情" :record="detail||selected" :loading="detailLoading" :error="detailError" :fields="[{key:'name',label:'项目名称'},{key:'customerName',label:'客户'},{key:'status',label:'状态'},{key:'ownerName',label:'负责人'},{key:'createdAt',label:'创建时间'}]" @close="selected=null" ><template #default><ProjectProgressPanel :status="String((detail||selected)?.status||'')"/><div class="form-actions"><button class="secondary" @click="edit">编辑</button></div></template></EntityDetailPanel></section></template>
